// The offline service worker of one app: keeps every file the app needs in Cache Storage, so an
// installed app (or a page opened before) starts and plays without a network.
// GENERATED by tools/sw-build.js from tools/sw-template.js — never edit a <folder>/sw.js by hand:
// change the template and run `node tools/sw-build.js`. Registered by update.js (AppUpdate.watch).
//
// - Install: downloads the whole file list below into a cache named after this version. Every
//   change to an app's files changes VERSION, so the browser installs the new worker after a
//   deploy and the app is complete offline again.
// - The page (a navigation): network first, so a deploy is seen at once; the cached copy when the
//   network fails or takes longer than PAGE_TIMEOUT_MS.
// - A file with ?v=N: from the cache, else from the network (then cached) — a new N is a new file.
// - A file without ?v: from the cache at once, refreshed from the network for the next start.
// - Offline and not cached under this exact address: the same file under any ?v= it was cached.
//
// The worker serves only its own folder (the scope). Cache names start with the scope's path,
// e.g. "/ivan/lift-logic/offline.<version>": every app on the shared origin keeps its own and
// deletes only its own old ones.

const VERSION = "9a29664eb561";
// Paths relative to this folder; './' is the page itself, ?v=N as the page links them.
const FILES = [
  "./",
  "apple-touch-icon.png?v=1",
  "constants.js?v=38",
  "core/audio.js?v=8",
  "core/cursor.js?v=1",
  "core/events.js?v=1",
  "core/icons.js?v=1",
  "core/input.js?v=6",
  "core/quality.js?v=1",
  "core/update.js?v=2",
  "core/utils.js?v=5",
  "data/icons.js?v=1",
  "data/milestones.js?v=1",
  "game.js?v=54",
  "icon-192.png?v=1",
  "icon-512.png?v=1",
  "icon-maskable-512.png?v=1",
  "icon.svg?v=2",
  "manifest.webmanifest?v=1",
  "render/render.js?v=10",
  "render/scenery.js?v=7",
  "sim/camera.js?v=1",
  "sim/demo.js?v=5",
  "sim/effects.js?v=2",
  "sim/fish.js?v=1",
  "sim/gulls.js?v=1",
  "sim/jellyfish.js?v=1",
  "sim/leaps.js?v=1",
  "sim/npc.js?v=2",
  "sim/player.js?v=2",
  "sim/records.js?v=1",
  "sim/spawn.js?v=1",
  "sim/state.js?v=1",
  "styles.css?v=12",
  "ui/dialogs.js?v=2",
  "ui/fireworks.js?v=2",
  "ui/hud.js?v=1",
  "ui/menu.js?v=1",
  "ui/overlay.js?v=1",
  "ui/sounds.js?v=1",
];
// false for the root gallery: its scope contains every game's folder, which belong to the games'
// own workers, so it serves only the files in its list.
const OWN_ALL = true;
const PAGE_TIMEOUT_MS = 4000; // how long the page waits for the network before taking the cached copy

const SCOPE = new URL(self.registration.scope);
const PREFIX = SCOPE.pathname + 'offline.';
const CACHE = PREFIX + VERSION;
const OWNED = new Set(FILES.map(f => f.replace(/\?.*$/, '').replace(/^\.\/$/, '')));

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // One by one rather than addAll: a file missing from the server costs that file, not the
    // whole offline copy. The page itself must come, or the install fails and is tried again.
    await Promise.all(FILES.map(async f => {
      try {
        const res = await fetch(new Request(new URL(f, SCOPE), { cache: 'no-cache' }));
        if (res.status === 200) await cache.put(new URL(f, SCOPE), res);
        else if (f === './') throw new Error('page ' + res.status);
      } catch (e) {
        if (f === './') throw e;
      }
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith(PREFIX) && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET' || req.headers.has('range')) return;
  const url = new URL(req.url);
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  const rel = url.pathname.slice(SCOPE.pathname.length);
  const isPage = req.mode === 'navigate';
  if (!OWN_ALL && !OWNED.has(rel === 'index.html' ? '' : rel)) return;
  // Anything else on the page itself (update.js looking for a new deploy) goes to the network
  // as it is: it must never be answered from the cache.
  if (!isPage && (rel === '' || rel === 'index.html')) return;
  event.respondWith(isPage ? page(event, req, rel) : file(event, req, url));
});

async function put(cache, key, res) {
  try { await cache.put(key, res); } catch (e) { /* storage full — the network copy still works */ }
}

async function page(event, req, rel) {
  const cache = await caches.open(CACHE);
  // index.html, the folder and the folder with a query (a sign-in coming back) are one page
  const key = rel === '' || rel === 'index.html' ? SCOPE.href : new URL(rel, SCOPE).href;
  const net = fetch(req);
  // kept even when the cached copy answered first: a late network page is still the next start's
  event.waitUntil(net.then(res => res.status === 200 && put(cache, key, res.clone()), () => {}));
  try {
    return await Promise.race([net, new Promise((_, no) => setTimeout(no, PAGE_TIMEOUT_MS))]);
  } catch (e) {
    const hit = await cache.match(key, { ignoreSearch: true });
    return hit || net; // nothing cached: keep waiting for the network (or its error)
  }
}

async function file(event, req, url) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(req);
  const load = () => fetch(req).then(async res => {
    if (res.status === 200) await put(cache, req, res.clone());
    return res;
  });
  if (hit) {
    if (!url.searchParams.has('v')) event.waitUntil(load().catch(() => {}));
    return hit;
  }
  try {
    return await load();
  } catch (e) {
    const old = await cache.match(req, { ignoreSearch: true });
    if (old) return old;
    throw e;
  }
}
